hani-design-system.css.old_str:
/* Dedicated square illustrations keep their full composition in the canonical slot. */
#app .ds-main-character-banner[data-scene-variant="illustration-218"]{grid-template-columns:minmax(0,54%) minmax(0,46%)}
#app .ds-main-character-banner[data-scene-variant="illustration-218"]:after{display:none}
#app .ds-main-character-banner[data-scene-variant="illustration-218"] .ds-main-character-banner__scene{position:relative;grid-column:2;grid-row:1;inset:auto;height:320px;background:#eee8f5}
#app .ds-main-character-banner[data-scene-variant="illustration-218"] .ds-main-character-banner__scene img{width:100%;height:100%;mask-image:none;-webkit-mask-image:none}
#app .ds-main-character-banner[data-scene-variant="illustration-218"] .ds-main-character-banner__copy{grid-row:1}
/* Character panoramas keep every staff member visible in the canonical slot. */
#app .ds-main-character-banner[data-scene-variant="illustration-wide-218"]{display:flex;flex-direction:column}
#app .ds-main-character-banner[data-scene-variant="illustration-wide-218"]:after{display:none}
#app .ds-main-character-banner[data-scene-variant="illustration-wide-218"] .ds-main-character-banner__scene{position:relative;inset:auto;height:auto;aspect-ratio:3/1;width:100%}
#app .ds-main-character-banner[data-scene-variant="illustration-wide-218"] .ds-main-character-banner__scene img{width:100%;height:100%;mask-image:none;-webkit-mask-image:none}
#app .ds-main-character-banner[data-scene-variant="illustration-wide-218"] .ds-main-character-banner__copy{min-height:0}
@media(max-width:700px){
 #app .ds-main-character-banner[data-scene-variant="illustration-218"]{display:flex;flex-direction:column}
 #app .ds-main-character-banner[data-scene-variant="illustration-218"] .ds-main-character-banner__scene{height:auto;aspect-ratio:1;width:100%}
 #app .ds-main-character-banner[data-scene-variant="illustration-218"] .ds-main-character-banner__copy{min-height:0}
}

